import 'dart:convert';

/// User preferences that can be serialised to and from JSON.
class Settings {
  /// Creates a set of settings.
  const Settings({
    required this.username,
    this.fontSize = 14,
    this.darkMode = false,
    this.tags = const [],
    this.locale = 'en',
  });

  /// The account name. Never empty.
  final String username;

  /// The preferred font size, within `8..72`.
  final int fontSize;

  /// Whether the dark colour scheme is selected.
  final bool darkMode;

  /// Free-form labels. No element is empty.
  final List<String> tags;

  /// The language tag, as two lowercase letters optionally followed by an
  /// underscore and two uppercase letters, such as `en` or `de_DE`.
  final String locale;

  /// Returns a JSON-encodable representation of these settings.
  Map<String, Object?> toJson() {
    return <String, Object?>{
      'username': username,
      'fontSize': fontSize,
      'darkMode': darkMode,
      'tags': List<String>.of(tags),
      'locale': locale,
    };
  }

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) {
      return true;
    }
    return other is Settings &&
        other.username == username &&
        other.fontSize == fontSize &&
        other.darkMode == darkMode &&
        other.locale == locale &&
        _sameTags(other.tags, tags);
  }

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags), locale);

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags, locale: $locale)';

  static bool _sameTags(List<String> a, List<String> b) {
    if (identical(a, b)) {
      return true;
    }
    if (a.length != b.length) {
      return false;
    }
    for (var i = 0; i < a.length; i++) {
      if (a[i] != b[i]) {
        return false;
      }
    }
    return true;
  }
}

/// Thrown when a JSON document cannot be read as a [Settings].
class SettingsFormatException implements Exception {
  /// Creates an exception describing why parsing failed.
  const SettingsFormatException(this.message);

  /// A human readable description that names the offending key, if any.
  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

/// Parses [json] into a [Settings].
///
/// Throws a [SettingsFormatException] if the text is not a JSON object, if a
/// required key is missing, or if a value has the wrong type or is out of
/// range. No other exception escapes this function.
Settings parseSettings(String json) {
  final Object? decoded;
  try {
    decoded = jsonDecode(json);
  } on FormatException catch (error) {
    throw SettingsFormatException('invalid JSON: ${error.message}');
  }

  if (decoded is! Map<String, Object?>) {
    throw const SettingsFormatException(
      'the top level value must be a JSON object',
    );
  }

  return Settings(
    username: _readUsername(decoded),
    fontSize: _readFontSize(decoded),
    darkMode: _readDarkMode(decoded),
    tags: _readTags(decoded),
    locale: _readLocale(decoded),
  );
}

String _readUsername(Map<String, Object?> map) {
  const key = 'username';
  if (!map.containsKey(key)) {
    throw const SettingsFormatException('missing required key "$key"');
  }
  final value = map[key];
  if (value is! String) {
    throw const SettingsFormatException('"$key" must be a string');
  }
  if (value.isEmpty) {
    throw const SettingsFormatException('"$key" must not be empty');
  }
  return value;
}

int _readFontSize(Map<String, Object?> map) {
  const key = 'fontSize';
  final value = map[key];
  if (value == null) {
    return 14;
  }
  final int size;
  if (value is int) {
    size = value;
  } else if (value is double && value == value.roundToDouble()) {
    size = value.toInt();
  } else {
    throw const SettingsFormatException('"$key" must be an integer');
  }
  if (size < 8 || size > 72) {
    throw const SettingsFormatException('"$key" must be within 8..72');
  }
  return size;
}

bool _readDarkMode(Map<String, Object?> map) {
  const key = 'darkMode';
  final value = map[key];
  if (value == null) {
    return false;
  }
  if (value is! bool) {
    throw const SettingsFormatException('"$key" must be a boolean');
  }
  return value;
}

List<String> _readTags(Map<String, Object?> map) {
  const key = 'tags';
  final value = map[key];
  if (value == null) {
    return const <String>[];
  }
  if (value is! List<Object?>) {
    throw const SettingsFormatException('"$key" must be a list of strings');
  }
  final tags = <String>[];
  for (final element in value) {
    if (element is! String) {
      throw const SettingsFormatException('"$key" must contain only strings');
    }
    if (element.isEmpty) {
      throw const SettingsFormatException(
        '"$key" must not contain an empty string',
      );
    }
    tags.add(element);
  }
  return List<String>.unmodifiable(tags);
}

/// Matches a language tag such as `en` or `de_DE`, and nothing else.
final RegExp _localePattern = RegExp(r'^[a-z]{2}(_[A-Z]{2})?$');

String _readLocale(Map<String, Object?> map) {
  const key = 'locale';
  final value = map[key];
  if (value == null) {
    return 'en';
  }
  if (value is! String) {
    throw const SettingsFormatException('"$key" must be a string');
  }
  if (!_localePattern.hasMatch(value)) {
    throw const SettingsFormatException(
      '"$key" must be two lowercase letters, optionally followed by an '
      'underscore and two uppercase letters',
    );
  }
  return value;
}

import 'dart:async';

import 'package:flutter/material.dart';

/// Counts down from [duration] to zero, one second at a time.
///
/// The object that creates a controller owns it and is responsible for
/// calling [dispose]; widgets that render it never do.
class CountdownController extends ChangeNotifier {
  CountdownController({required Duration duration})
    : _duration = duration,
      _remaining = duration;

  static const Duration _tick = Duration(seconds: 1);

  final Duration _duration;

  Duration _remaining;
  Timer? _timer;

  /// Time left before the countdown reaches zero.
  Duration get remaining => _remaining;

  /// Whether the countdown is currently ticking down.
  bool get isRunning => _timer != null;

  /// Starts ticking. Does nothing while running or once [remaining] is zero.
  void start() {
    if (isRunning || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_tick, _onTick);
    notifyListeners();
  }

  /// Stops ticking, keeping [remaining]. Does nothing when not running.
  void pause() {
    if (!isRunning) {
      return;
    }
    _cancelTimer();
    notifyListeners();
  }

  /// Adds [extra] to [remaining], notifying listeners once.
  ///
  /// A running countdown keeps ticking from the new value; a paused or
  /// finished one stays stopped, so [start] picks it up again.
  ///
  /// Throws an [ArgumentError] when [extra] is zero or negative, leaving the
  /// countdown untouched.
  void addTime(Duration extra) {
    if (extra <= Duration.zero) {
      throw ArgumentError.value(extra, 'extra', 'must be greater than zero');
    }
    _remaining += extra;
    notifyListeners();
  }

  /// Stops ticking and restores [remaining] to the original duration.
  void reset() {
    _cancelTimer();
    _remaining = _duration;
    notifyListeners();
  }

  void _onTick(Timer timer) {
    if (_remaining <= _tick) {
      _remaining = Duration.zero;
      _cancelTimer();
    } else {
      _remaining -= _tick;
    }
    notifyListeners();
  }

  void _cancelTimer() {
    _timer?.cancel();
    _timer = null;
  }

  @override
  void dispose() {
    _cancelTimer();
    super.dispose();
  }
}

/// Shows the remaining time of a [CountdownController] as `mm:ss` alongside
/// start, pause, reset and add-ten-seconds buttons.
class CountdownTimer extends StatefulWidget {
  const CountdownTimer({required this.controller, super.key, this.onFinished});

  /// The countdown to display and drive. Owned by the caller.
  final CountdownController controller;

  /// Called once each time the countdown reaches zero.
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  static const Duration _extraTime = Duration(seconds: 10);

  bool _finishedNotified = false;

  @override
  void initState() {
    super.initState();
    _attach(widget.controller);
  }

  @override
  void didUpdateWidget(covariant CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_onControllerChanged);
      _attach(widget.controller);
    }
  }

  @override
  void dispose() {
    // The controller belongs to the caller, so only the listener goes away.
    widget.controller.removeListener(_onControllerChanged);
    super.dispose();
  }

  void _attach(CountdownController controller) {
    // An already finished controller must not fire [onFinished] again.
    _finishedNotified = controller.remaining == Duration.zero;
    controller.addListener(_onControllerChanged);
  }

  void _onControllerChanged() {
    setState(() {});
    final bool finished = widget.controller.remaining == Duration.zero;
    if (finished && !_finishedNotified) {
      _finishedNotified = true;
      widget.onFinished?.call();
    } else if (!finished) {
      _finishedNotified = false;
    }
  }

  static String _format(Duration remaining) {
    final String minutes = remaining.inMinutes.toString().padLeft(2, '0');
    final String seconds = (remaining.inSeconds % 60).toString().padLeft(
      2,
      '0',
    );
    return '$minutes:$seconds';
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: <Widget>[
        Text(_format(widget.controller.remaining)),
        Row(
          mainAxisSize: MainAxisSize.min,
          children: <Widget>[
            TextButton(
              onPressed: widget.controller.start,
              child: const Text('Start'),
            ),
            TextButton(
              onPressed: widget.controller.pause,
              child: const Text('Pause'),
            ),
            TextButton(
              onPressed: widget.controller.reset,
              child: const Text('Reset'),
            ),
            TextButton(
              onPressed: () => widget.controller.addTime(_extraTime),
              child: const Text('+10s'),
            ),
          ],
        ),
      ],
    );
  }
}

import 'dart:async';

import 'package:flutter/foundation.dart';

/// Fetches the results for [query].
typedef SearchFetcher = Future<List<String>> Function(String query);

/// The state of the latest search.
enum SearchStatus { idle, loading, success, error }

/// Runs debounced searches through a [SearchFetcher] and exposes their state.
class SearchModel extends ChangeNotifier {
  SearchModel({
    required SearchFetcher fetcher,
    Duration debounce = const Duration(milliseconds: 300),
  }) : _runSearch = fetcher,
       _debounceDuration = debounce;

  final SearchFetcher _runSearch;
  final Duration _debounceDuration;

  Timer? _timer;
  bool _disposed = false;

  /// Identifies the search a pending timer or an in-flight fetch belongs to.
  ///
  /// Bumped whenever the query changes or the model is disposed, so that
  /// anything started for an earlier query can be recognised and dropped.
  int _generation = 0;

  SearchStatus _status = SearchStatus.idle;
  String _query = '';
  List<String> _results = const <String>[];
  Object? _error;

  SearchStatus get status => _status;

  String get query => _query;

  List<String> get results => _results;

  Object? get error => _error;

  /// Records [text] as the current query and schedules a fetch for it.
  ///
  /// The fetch runs once the debounce has elapsed without another change.
  /// Text equal to the current query is ignored.
  void onQueryChanged(String text) {
    if (_disposed || text == _query) {
      return;
    }

    _query = text;
    _timer?.cancel();
    _timer = null;
    // Anything already scheduled or in flight belongs to an older query.
    _generation++;

    if (text.isEmpty) {
      _status = SearchStatus.idle;
      _results = const <String>[];
      _error = null;
      notifyListeners();
      return;
    }

    final int generation = _generation;
    _timer = Timer(_debounceDuration, () {
      _timer = null;
      unawaited(_fetch(text, generation));
    });
    notifyListeners();
  }

  /// Re-runs the fetch for the current query straight away.
  ///
  /// Only takes effect while [status] is [SearchStatus.error]; the debounce is
  /// skipped, so the status becomes [SearchStatus.loading] before this returns.
  void retry() {
    if (_disposed || _status != SearchStatus.error) {
      return;
    }

    _timer?.cancel();
    _timer = null;
    // Supersede anything scheduled or in flight for the previous attempt.
    _generation++;
    unawaited(_fetch(_query, _generation));
  }

  Future<void> _fetch(String text, int generation) async {
    if (_disposed || generation != _generation) {
      return;
    }

    _status = SearchStatus.loading;
    _error = null;
    notifyListeners();

    try {
      final List<String> results = await _runSearch(text);
      if (_disposed || generation != _generation) {
        return;
      }
      _status = SearchStatus.success;
      _results = List<String>.unmodifiable(results);
      _error = null;
    } on Object catch (error) {
      if (_disposed || generation != _generation) {
        return;
      }
      _status = SearchStatus.error;
      _results = const <String>[];
      _error = error;
    }
    notifyListeners();
  }

  @override
  void notifyListeners() {
    if (_disposed) {
      return;
    }
    super.notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _timer?.cancel();
    _timer = null;
    _generation++;
    super.dispose();
  }
}

import 'dart:async';

import 'package:flutter/material.dart';

/// Counts down from [duration] to zero, one second at a time.
///
/// The object that creates the controller owns it and is responsible for
/// calling [dispose]; a [CountdownTimer] using it will never dispose it.
class CountdownController extends ChangeNotifier {
  CountdownController({required Duration duration})
    : _duration = duration,
      _remaining = duration;

  static const Duration _tick = Duration(seconds: 1);

  final Duration _duration;

  Duration _remaining;
  Timer? _timer;

  /// The time left before the countdown finishes.
  ///
  /// Starts out at the `duration` the controller was created with.
  Duration get remaining => _remaining;

  /// Whether the countdown is currently ticking down.
  bool get isRunning => _timer != null;

  /// Starts ticking.
  ///
  /// Does nothing when the countdown is already running or has finished.
  void start() {
    if (isRunning || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_tick, (_) => _onTick());
  }

  /// Stops ticking, keeping [remaining] where it is.
  ///
  /// Does nothing when the countdown is not running.
  void pause() {
    if (!isRunning) {
      return;
    }
    _cancel();
    notifyListeners();
  }

  /// Adds [extra] to [remaining], notifying listeners once.
  ///
  /// Works while running, in which case ticking carries on from the new
  /// value, while paused, and after the countdown has finished, in which
  /// case [remaining] becomes [extra] and [start] runs it again.
  ///
  /// Throws an [ArgumentError] when [extra] is not positive, leaving the
  /// countdown untouched.
  void addTime(Duration extra) {
    if (extra <= Duration.zero) {
      throw ArgumentError.value(extra, 'extra', 'must be greater than zero');
    }
    _remaining += extra;
    notifyListeners();
  }

  /// Stops ticking and puts [remaining] back to the original duration.
  void reset() {
    _cancel();
    _remaining = _duration;
    notifyListeners();
  }

  void _onTick() {
    final Duration next = _remaining - _tick;
    if (next <= Duration.zero) {
      _remaining = Duration.zero;
      _cancel();
    } else {
      _remaining = next;
    }
    notifyListeners();
  }

  void _cancel() {
    _timer?.cancel();
    _timer = null;
  }

  @override
  void dispose() {
    _cancel();
    super.dispose();
  }
}

/// Displays the [controller]'s remaining time and controls for it.
class CountdownTimer extends StatefulWidget {
  const CountdownTimer({required this.controller, super.key, this.onFinished});

  /// The countdown to display. Owned by the caller, never disposed here.
  final CountdownController controller;

  /// Called once, when the countdown reaches zero.
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  bool _finished = false;

  @override
  void initState() {
    super.initState();
    widget.controller.addListener(_onChanged);
  }

  @override
  void didUpdateWidget(CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_onChanged);
      widget.controller.addListener(_onChanged);
      _finished = false;
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_onChanged);
    super.dispose();
  }

  void _onChanged() {
    if (!mounted) {
      return;
    }
    setState(() {});
    if (widget.controller.remaining != Duration.zero) {
      // Time was put back on the clock, so zero can be reached again.
      _finished = false;
    } else if (!_finished) {
      _finished = true;
      widget.onFinished?.call();
    }
  }

  static String _format(Duration remaining) {
    final int totalSeconds = remaining.inSeconds;
    final String minutes = '${totalSeconds ~/ 60}'.padLeft(2, '0');
    final String seconds = '${totalSeconds % 60}'.padLeft(2, '0');
    return '$minutes:$seconds';
  }

  @override
  Widget build(BuildContext context) {
    final CountdownController controller = widget.controller;
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: <Widget>[
        Text(_format(controller.remaining)),
        Row(
          mainAxisSize: MainAxisSize.min,
          children: <Widget>[
            TextButton(onPressed: controller.start, child: const Text('Start')),
            TextButton(onPressed: controller.pause, child: const Text('Pause')),
            TextButton(onPressed: controller.reset, child: const Text('Reset')),
            TextButton(
              onPressed: () => controller.addTime(const Duration(seconds: 10)),
              child: const Text('+10s'),
            ),
          ],
        ),
      ],
    );
  }
}

import 'dart:async';

import 'package:flutter/foundation.dart';

/// Fetches the results for [query].
typedef SearchFetcher = Future<List<String>> Function(String query);

/// The lifecycle of the search for the current query.
enum SearchStatus { idle, loading, success, error }

/// Debounced search over a [SearchFetcher], exposed as a [ChangeNotifier].
class SearchModel extends ChangeNotifier {
  factory SearchModel({
    required SearchFetcher fetcher,
    Duration debounce = const Duration(milliseconds: 300),
  }) => SearchModel._(fetcher, debounce);

  SearchModel._(this._fetcher, this._debounce);

  final SearchFetcher _fetcher;
  final Duration _debounce;

  Timer? _timer;
  bool _disposed = false;

  /// Identifies the newest fetch; responses carrying an older id are stale.
  int _requestId = 0;

  SearchStatus _status = SearchStatus.idle;
  String _query = '';
  List<String> _results = const <String>[];
  Object? _error;

  SearchStatus get status => _status;

  String get query => _query;

  List<String> get results => List<String>.unmodifiable(_results);

  Object? get error => _error;

  void onQueryChanged(String text) {
    if (_disposed || text == _query) return;

    _query = text;
    _timer?.cancel();
    _timer = null;
    // Any response still in flight belongs to an older query now.
    _requestId++;

    if (text.isEmpty) {
      _status = SearchStatus.idle;
      _results = const <String>[];
      _error = null;
      notifyListeners();
      return;
    }

    notifyListeners();
    _timer = Timer(_debounce, () {
      _timer = null;
      _start(text);
    });
  }

  /// Re-runs the fetch for the current query, skipping the debounce.
  ///
  /// Does nothing unless [status] is [SearchStatus.error].
  void retry() {
    if (_disposed || _status != SearchStatus.error) return;

    // A pending debounce would only repeat the fetch we are about to start.
    _timer?.cancel();
    _timer = null;
    _start(_query);
  }

  Future<void> _start(String text) async {
    if (_disposed) return;

    final id = ++_requestId;
    _status = SearchStatus.loading;
    _error = null;
    notifyListeners();

    try {
      final fetched = await _fetcher(text);
      if (_disposed || id != _requestId) return;
      _status = SearchStatus.success;
      _results = List<String>.of(fetched);
      _error = null;
    } catch (e) {
      if (_disposed || id != _requestId) return;
      _status = SearchStatus.error;
      _results = const <String>[];
      _error = e;
    }
    notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }
}

import 'dart:convert';

/// User preferences that can be serialised to and from JSON.
class Settings {
  const Settings({
    required this.username,
    this.fontSize = 14,
    this.darkMode = false,
    this.tags = const [],
    this.locale = 'en',
  });

  /// Display name of the user. Never empty.
  final String username;

  /// Editor font size, always within [minFontSize]..[maxFontSize].
  final int fontSize;

  /// Whether the dark colour scheme is active.
  final bool darkMode;

  /// Free-form labels. Individual tags are never empty.
  final List<String> tags;

  /// Language tag, always matching [localePattern].
  final String locale;

  /// Smallest accepted value for [fontSize].
  static const int minFontSize = 8;

  /// Largest accepted value for [fontSize].
  static const int maxFontSize = 72;

  /// The shape of an accepted [locale]: two lowercase ASCII letters, followed
  /// by an optional underscore and two uppercase ASCII letters.
  static final RegExp localePattern = RegExp(r'^[a-z]{2}(?:_[A-Z]{2})?$');

  /// The JSON representation understood by [parseSettings].
  Map<String, Object?> toJson() {
    return <String, Object?>{
      'username': username,
      'fontSize': fontSize,
      'darkMode': darkMode,
      'tags': List<String>.of(tags),
      'locale': locale,
    };
  }

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) {
      return true;
    }
    if (other is! Settings) {
      return false;
    }
    if (other.username != username ||
        other.fontSize != fontSize ||
        other.darkMode != darkMode ||
        other.locale != locale ||
        other.tags.length != tags.length) {
      return false;
    }
    for (var i = 0; i < tags.length; i++) {
      if (other.tags[i] != tags[i]) {
        return false;
      }
    }
    return true;
  }

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags), locale);

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags, locale: $locale)';
}

/// Thrown when a document cannot be turned into a valid [Settings].
class SettingsFormatException implements Exception {
  const SettingsFormatException(this.message);

  /// Human readable explanation naming the offending key, when there is one.
  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

/// Decodes [json] into [Settings].
///
/// Throws a [SettingsFormatException] if the text is not a JSON object, if a
/// required key is missing, or if a value has the wrong type or is out of
/// range. No other exception escapes this function.
Settings parseSettings(String json) {
  final Object? decoded;
  try {
    decoded = jsonDecode(json);
  } on FormatException catch (error) {
    throw SettingsFormatException('invalid JSON: ${error.message}');
  } on Object {
    throw const SettingsFormatException('invalid JSON');
  }

  if (decoded is! Map<String, Object?>) {
    throw const SettingsFormatException(
      'the top level value must be a JSON object',
    );
  }

  return Settings(
    username: _readUsername(decoded),
    fontSize: _readFontSize(decoded),
    darkMode: _readDarkMode(decoded),
    tags: _readTags(decoded),
    locale: _readLocale(decoded),
  );
}

String _readUsername(Map<String, Object?> map) {
  const key = 'username';
  if (!map.containsKey(key)) {
    throw const SettingsFormatException('"$key" is required');
  }
  final value = map[key];
  if (value is! String) {
    throw const SettingsFormatException('"$key" must be a string');
  }
  if (value.isEmpty) {
    throw const SettingsFormatException('"$key" must not be empty');
  }
  return value;
}

int _readFontSize(Map<String, Object?> map) {
  const key = 'fontSize';
  if (!map.containsKey(key)) {
    return 14;
  }
  final value = map[key];
  final int size;
  if (value is int) {
    size = value;
  } else if (value is double &&
      value.isFinite &&
      value == value.roundToDouble()) {
    size = value.toInt();
  } else {
    throw const SettingsFormatException('"$key" must be an integer');
  }
  if (size < Settings.minFontSize || size > Settings.maxFontSize) {
    throw const SettingsFormatException(
      '"$key" must be between ${Settings.minFontSize} and '
      '${Settings.maxFontSize}',
    );
  }
  return size;
}

bool _readDarkMode(Map<String, Object?> map) {
  const key = 'darkMode';
  if (!map.containsKey(key)) {
    return false;
  }
  final value = map[key];
  if (value is! bool) {
    throw const SettingsFormatException('"$key" must be a boolean');
  }
  return value;
}

List<String> _readTags(Map<String, Object?> map) {
  const key = 'tags';
  if (!map.containsKey(key)) {
    return const <String>[];
  }
  final value = map[key];
  if (value is! List) {
    throw const SettingsFormatException('"$key" must be a list of strings');
  }
  final tags = <String>[];
  for (final entry in value) {
    if (entry is! String) {
      throw const SettingsFormatException('"$key" must only contain strings');
    }
    if (entry.isEmpty) {
      throw const SettingsFormatException(
        '"$key" must not contain an empty string',
      );
    }
    tags.add(entry);
  }
  return List<String>.unmodifiable(tags);
}

String _readLocale(Map<String, Object?> map) {
  const key = 'locale';
  if (!map.containsKey(key)) {
    return 'en';
  }
  final value = map[key];
  if (value is! String) {
    throw const SettingsFormatException('"$key" must be a string');
  }
  if (!Settings.localePattern.hasMatch(value)) {
    throw const SettingsFormatException(
      '"$key" must be two lowercase letters, optionally followed by an '
      'underscore and two uppercase letters',
    );
  }
  return value;
}

import 'dart:async';

import 'package:flutter/material.dart';

const Duration _tick = Duration(seconds: 1);
const Duration _bonus = Duration(seconds: 10);

/// Counts down from [duration] to zero, one second at a time.
///
/// The countdown is driven by a timer that is owned by this controller and
/// cancelled when the controller is disposed. Listeners are notified on every
/// tick as well as whenever the running state changes.
class CountdownController extends ChangeNotifier {
  /// Creates a controller whose [remaining] starts at [duration].
  CountdownController({required this.duration}) : _remaining = duration;

  /// The value [remaining] starts at and is restored to by [reset].
  final Duration duration;

  Duration _remaining;
  Timer? _timer;

  /// The time left before the countdown finishes.
  Duration get remaining => _remaining;

  /// Whether the countdown is currently ticking.
  bool get isRunning => _timer != null;

  /// Starts ticking.
  ///
  /// Does nothing while already running or when [remaining] is already zero.
  void start() {
    if (isRunning || _remaining <= Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_tick, (_) => _onTick());
    notifyListeners();
  }

  /// Stops ticking, keeping [remaining] where it is.
  ///
  /// Does nothing when not running.
  void pause() {
    if (!isRunning) {
      return;
    }
    _cancel();
    notifyListeners();
  }

  /// Adds [extra] to [remaining], notifying listeners once.
  ///
  /// Ticking is left as it is: a running countdown keeps going from the new
  /// value, and a paused or finished one stays stopped until [start] is called.
  /// Throws an [ArgumentError] when [extra] is not positive, in which case
  /// nothing changes.
  void addTime(Duration extra) {
    if (extra <= Duration.zero) {
      throw ArgumentError.value(extra, 'extra', 'must be greater than zero');
    }
    _remaining = _remaining + extra;
    notifyListeners();
  }

  /// Stops ticking and restores [remaining] to [duration].
  void reset() {
    _cancel();
    _remaining = duration;
    notifyListeners();
  }

  void _onTick() {
    _remaining = _remaining - _tick;
    if (_remaining <= Duration.zero) {
      _remaining = Duration.zero;
      _cancel();
    }
    notifyListeners();
  }

  void _cancel() {
    _timer?.cancel();
    _timer = null;
  }

  @override
  void dispose() {
    _cancel();
    super.dispose();
  }
}

/// Displays the [controller]'s remaining time as `mm:ss` with start, pause,
/// reset and `+10s` buttons.
///
/// The controller is owned by the caller: this widget never disposes it, and
/// the same controller can be handed to another [CountdownTimer] afterwards.
class CountdownTimer extends StatefulWidget {
  /// Creates a countdown display driven by [controller].
  const CountdownTimer({required this.controller, super.key, this.onFinished});

  /// The countdown to display and control.
  final CountdownController controller;

  /// Called once each time the countdown reaches zero.
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  late bool _finished;

  @override
  void initState() {
    super.initState();
    _finished = widget.controller.remaining <= Duration.zero;
    widget.controller.addListener(_handleChange);
  }

  @override
  void didUpdateWidget(CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_handleChange);
      _finished = widget.controller.remaining <= Duration.zero;
      widget.controller.addListener(_handleChange);
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_handleChange);
    super.dispose();
  }

  void _handleChange() {
    setState(() {});
    if (widget.controller.remaining > Duration.zero) {
      _finished = false;
      return;
    }
    if (!_finished) {
      _finished = true;
      widget.onFinished?.call();
    }
  }

  void _addBonus() => widget.controller.addTime(_bonus);

  static String _format(Duration remaining) {
    final String minutes = remaining.inMinutes.toString().padLeft(2, '0');
    final String seconds = (remaining.inSeconds % 60).toString().padLeft(
      2,
      '0',
    );
    return '$minutes:$seconds';
  }

  @override
  Widget build(BuildContext context) {
    final CountdownController controller = widget.controller;
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: <Widget>[
        Text(_format(controller.remaining)),
        Row(
          mainAxisSize: MainAxisSize.min,
          children: <Widget>[
            TextButton(onPressed: controller.start, child: const Text('Start')),
            TextButton(onPressed: controller.pause, child: const Text('Pause')),
            TextButton(onPressed: controller.reset, child: const Text('Reset')),
            TextButton(onPressed: _addBonus, child: const Text('+10s')),
          ],
        ),
      ],
    );
  }
}

import 'dart:async';

import 'package:flutter/foundation.dart';

/// Fetches the results for [query].
typedef SearchFetcher = Future<List<String>> Function(String query);

/// The state of the latest search.
enum SearchStatus { idle, loading, success, error }

/// Debounces query changes and keeps the results of the latest search.
class SearchModel extends ChangeNotifier {
  SearchModel({
    required this._fetcher,
    this._debounce = const Duration(milliseconds: 300),
  });

  final SearchFetcher _fetcher;
  final Duration _debounce;

  Timer? _timer;
  bool _disposed = false;

  /// Identifies the latest started fetch; responses of any other are stale.
  int _requestId = 0;

  SearchStatus _status = SearchStatus.idle;
  String _query = '';
  List<String> _results = const <String>[];
  Object? _error;

  SearchStatus get status => _status;

  /// The latest text passed to [onQueryChanged].
  String get query => _query;

  List<String> get results => _results;

  /// The error of the latest failed fetch, or `null`.
  Object? get error => _error;

  void onQueryChanged(String text) {
    if (_disposed || text == _query) {
      return;
    }
    _query = text;
    _timer?.cancel();
    _timer = null;

    if (text.isEmpty) {
      // Drop whatever is in flight for an earlier query.
      _requestId++;
      _status = SearchStatus.idle;
      _results = const <String>[];
      _error = null;
      notifyListeners();
      return;
    }

    _timer = Timer(_debounce, () {
      _timer = null;
      _startFetch(_query);
    });
    notifyListeners();
  }

  /// Re-runs the fetch for [query] at once, skipping the debounce.
  ///
  /// Does nothing unless [status] is [SearchStatus.error].
  void retry() {
    if (_disposed || _status != SearchStatus.error) {
      return;
    }
    // A pending debounce would only fetch the same query again.
    _timer?.cancel();
    _timer = null;
    _startFetch(_query);
  }

  Future<void> _startFetch(String text) async {
    if (_disposed) {
      return;
    }
    final id = ++_requestId;
    _status = SearchStatus.loading;
    _error = null;
    notifyListeners();

    List<String> fetched;
    try {
      fetched = await _fetcher(text);
    } catch (error) {
      if (_isStale(id, text)) {
        return;
      }
      _status = SearchStatus.error;
      _error = error;
      _results = const <String>[];
      notifyListeners();
      return;
    }

    if (_isStale(id, text)) {
      return;
    }
    _status = SearchStatus.success;
    _error = null;
    _results = List<String>.unmodifiable(fetched);
    notifyListeners();
  }

  /// Whether the response of the fetch [id] for [text] may still be applied.
  ///
  /// A later fetch, or a query change that has not started its fetch yet,
  /// makes an earlier response stale.
  bool _isStale(int id, String text) =>
      _disposed || id != _requestId || text != _query;

  @override
  void notifyListeners() {
    if (_disposed) {
      return;
    }
    super.notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }
}

import 'dart:convert';

/// Thrown when a settings document cannot be parsed into a [Settings].
class SettingsFormatException implements Exception {
  /// Creates an exception describing why parsing failed.
  const SettingsFormatException(this.message);

  /// Human readable description of the problem, naming the offending key.
  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

/// User preferences for the app.
class Settings {
  /// Creates a settings value.
  const Settings({
    required this.username,
    this.fontSize = 14,
    this.darkMode = false,
    this.tags = const [],
    this.locale = 'en',
  });

  /// Name of the user the settings belong to. Must not be empty.
  final String username;

  /// Editor font size in logical pixels. Must be within `8..72`.
  final int fontSize;

  /// Whether the dark theme is selected.
  final bool darkMode;

  /// Free form labels. Every tag must be non-empty.
  final List<String> tags;

  /// Language tag such as `en` or `de_DE`.
  ///
  /// Two lowercase ASCII letters, optionally followed by an underscore and two
  /// uppercase ASCII letters.
  final String locale;

  /// Converts these settings into a JSON compatible map.
  Map<String, Object?> toJson() => <String, Object?>{
    'username': username,
    'fontSize': fontSize,
    'darkMode': darkMode,
    'tags': List<String>.of(tags),
    'locale': locale,
  };

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) {
      return true;
    }
    return other is Settings &&
        other.username == username &&
        other.fontSize == fontSize &&
        other.darkMode == darkMode &&
        other.locale == locale &&
        _tagsEqual(other.tags, tags);
  }

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags), locale);

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags, locale: $locale)';

  static bool _tagsEqual(List<String> a, List<String> b) {
    if (identical(a, b)) {
      return true;
    }
    if (a.length != b.length) {
      return false;
    }
    for (var i = 0; i < a.length; i++) {
      if (a[i] != b[i]) {
        return false;
      }
    }
    return true;
  }
}

/// Parses [json] into a [Settings].
///
/// Throws a [SettingsFormatException] if the text is not a JSON object, if a
/// required key is missing, or if a value has the wrong type or is out of
/// range. No other exception type escapes this function.
Settings parseSettings(String json) {
  final Object? decoded;
  try {
    decoded = jsonDecode(json);
  } on FormatException catch (error) {
    throw SettingsFormatException('invalid JSON: ${error.message}');
  }

  if (decoded is! Map<String, Object?>) {
    throw const SettingsFormatException('top level value must be an object');
  }

  return Settings(
    username: _readUsername(decoded),
    fontSize: _readFontSize(decoded),
    darkMode: _readDarkMode(decoded),
    tags: _readTags(decoded),
    locale: _readLocale(decoded),
  );
}

String _readUsername(Map<String, Object?> map) {
  const key = 'username';
  if (!map.containsKey(key)) {
    throw const SettingsFormatException('missing required key "$key"');
  }
  final value = map[key];
  if (value is! String) {
    throw const SettingsFormatException('"$key" must be a string');
  }
  if (value.isEmpty) {
    throw const SettingsFormatException('"$key" must not be empty');
  }
  return value;
}

int _readFontSize(Map<String, Object?> map) {
  const key = 'fontSize';
  if (!map.containsKey(key)) {
    return 14;
  }
  final value = map[key];
  final int size;
  if (value is int) {
    size = value;
  } else if (value is double &&
      value.isFinite &&
      value == value.roundToDouble()) {
    size = value.toInt();
  } else {
    throw const SettingsFormatException('"$key" must be an integer');
  }
  if (size < 8 || size > 72) {
    throw const SettingsFormatException('"$key" must be within 8..72');
  }
  return size;
}

bool _readDarkMode(Map<String, Object?> map) {
  const key = 'darkMode';
  if (!map.containsKey(key)) {
    return false;
  }
  final value = map[key];
  if (value is! bool) {
    throw const SettingsFormatException('"$key" must be a boolean');
  }
  return value;
}

List<String> _readTags(Map<String, Object?> map) {
  const key = 'tags';
  if (!map.containsKey(key)) {
    return const <String>[];
  }
  final value = map[key];
  if (value is! List<Object?>) {
    throw const SettingsFormatException('"$key" must be a list of strings');
  }
  final tags = <String>[];
  for (final entry in value) {
    if (entry is! String) {
      throw const SettingsFormatException('"$key" must contain only strings');
    }
    if (entry.isEmpty) {
      throw const SettingsFormatException('"$key" entries must not be empty');
    }
    tags.add(entry);
  }
  return List<String>.unmodifiable(tags);
}

/// Matches `en` and `de_DE`, but not `EN`, `de-DE`, `deu` or `de_de`.
final RegExp _localePattern = RegExp(r'^[a-z]{2}(_[A-Z]{2})?$');

String _readLocale(Map<String, Object?> map) {
  const key = 'locale';
  if (!map.containsKey(key)) {
    return 'en';
  }
  final value = map[key];
  if (value is! String) {
    throw const SettingsFormatException('"$key" must be a string');
  }
  if (!_localePattern.hasMatch(value)) {
    throw const SettingsFormatException(
      '"$key" must look like "en" or "de_DE"',
    );
  }
  return value;
}

import 'dart:async';

import 'package:flutter/material.dart';

/// Counts down from [duration] to zero, one second at a time.
///
/// The object that creates a controller owns it and is responsible for
/// calling [dispose]; [CountdownTimer] never disposes the controller it is
/// given.
class CountdownController extends ChangeNotifier {
  CountdownController({required Duration duration})
    : _duration = duration,
      _remaining = duration;

  static const Duration _tick = Duration(seconds: 1);

  final Duration _duration;

  Duration _remaining;
  Timer? _timer;

  /// The time left before the countdown finishes.
  Duration get remaining => _remaining;

  /// Whether the countdown is currently ticking.
  bool get isRunning => _timer != null;

  /// Starts ticking.
  ///
  /// Does nothing while the countdown is already running or when there is no
  /// time left.
  void start() {
    if (isRunning || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_tick, _onTick);
  }

  /// Stops ticking, keeping [remaining] where it is.
  ///
  /// Does nothing when the countdown is not running.
  void pause() {
    if (!isRunning) {
      return;
    }
    _stop();
  }

  /// Adds [extra] to [remaining], notifying listeners once.
  ///
  /// Works while running, in which case ticking carries on from the new
  /// value, while paused, and after the countdown has finished, in which case
  /// [remaining] becomes [extra] and [start] runs the countdown again.
  ///
  /// Throws an [ArgumentError] when [extra] is zero or negative, leaving the
  /// countdown untouched.
  void addTime(Duration extra) {
    if (extra <= Duration.zero) {
      throw ArgumentError.value(extra, 'extra', 'must be greater than zero');
    }
    _remaining += extra;
    notifyListeners();
  }

  /// Stops ticking and sets [remaining] back to the initial duration.
  void reset() {
    _stop();
    _remaining = _duration;
    notifyListeners();
  }

  @override
  void dispose() {
    _stop();
    super.dispose();
  }

  void _onTick(Timer timer) {
    final Duration next = _remaining - _tick;
    if (next <= Duration.zero) {
      _remaining = Duration.zero;
      _stop();
    } else {
      _remaining = next;
    }
    notifyListeners();
  }

  void _stop() {
    _timer?.cancel();
    _timer = null;
  }
}

/// Displays the [controller]'s remaining time as `mm:ss` with start, pause,
/// reset and `+10s` buttons.
class CountdownTimer extends StatefulWidget {
  const CountdownTimer({super.key, required this.controller, this.onFinished});

  /// The countdown to display and drive. Owned by the caller.
  final CountdownController controller;

  /// Called once each time the countdown reaches zero.
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  static const Duration _bonus = Duration(seconds: 10);

  bool _finishedReported = false;

  @override
  void initState() {
    super.initState();
    _subscribe(widget.controller);
  }

  @override
  void didUpdateWidget(covariant CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_handleUpdate);
      _subscribe(widget.controller);
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_handleUpdate);
    super.dispose();
  }

  void _subscribe(CountdownController controller) {
    _finishedReported = controller.remaining == Duration.zero;
    controller.addListener(_handleUpdate);
  }

  void _handleUpdate() {
    if (!mounted) {
      return;
    }
    setState(() {});
    if (widget.controller.remaining == Duration.zero) {
      if (!_finishedReported) {
        _finishedReported = true;
        widget.onFinished?.call();
      }
    } else {
      _finishedReported = false;
    }
  }

  static String _format(Duration remaining) {
    final String minutes = remaining.inMinutes.toString().padLeft(2, '0');
    final String seconds = (remaining.inSeconds % Duration.secondsPerMinute)
        .toString()
        .padLeft(2, '0');
    return '$minutes:$seconds';
  }

  @override
  Widget build(BuildContext context) {
    final CountdownController controller = widget.controller;
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: <Widget>[
        Text(_format(controller.remaining)),
        Row(
          mainAxisSize: MainAxisSize.min,
          children: <Widget>[
            TextButton(onPressed: controller.start, child: const Text('Start')),
            TextButton(onPressed: controller.pause, child: const Text('Pause')),
            TextButton(onPressed: controller.reset, child: const Text('Reset')),
            TextButton(
              onPressed: () => controller.addTime(_bonus),
              child: const Text('+10s'),
            ),
          ],
        ),
      ],
    );
  }
}

import 'dart:async';
import 'dart:collection';

import 'package:flutter/foundation.dart';

/// Fetches the results for [query].
typedef SearchFetcher = Future<List<String>> Function(String query);

/// The state of the latest search.
enum SearchStatus { idle, loading, success, error }

/// Debounces query changes and exposes the state of the resulting search.
class SearchModel extends ChangeNotifier {
  /// Creates a model that calls [fetcher] once [debounce] has passed without
  /// another query change.
  SearchModel({
    required SearchFetcher fetcher,
    Duration debounce = const Duration(milliseconds: 300),
  }) {
    // Assigned in the body because named parameters cannot be private, so
    // these fields cannot be initializing formals.
    _fetcher = fetcher;
    _debounce = debounce;
  }

  late final SearchFetcher _fetcher;
  late final Duration _debounce;

  Timer? _timer;
  bool _disposed = false;

  /// Identifies the newest accepted query; responses stamped with an older id
  /// are stale and dropped.
  int _requestId = 0;

  SearchStatus _status = SearchStatus.idle;
  String _query = '';
  List<String> _results = const <String>[];
  Object? _error;

  /// The state of the latest search.
  SearchStatus get status => _status;

  /// The latest text passed to [onQueryChanged].
  String get query => _query;

  /// The results of the latest successful fetch.
  List<String> get results => UnmodifiableListView<String>(_results);

  /// The error of the latest failed fetch, or `null`.
  Object? get error => _error;

  /// Stores [text] and schedules a fetch for it.
  void onQueryChanged(String text) {
    if (_disposed || text == _query) {
      return;
    }

    _timer?.cancel();
    _timer = null;
    _requestId++;
    _query = text;

    if (text.isEmpty) {
      _status = SearchStatus.idle;
      _results = const <String>[];
      _error = null;
      notifyListeners();
      return;
    }

    notifyListeners();
    final int requestId = _requestId;
    _timer = Timer(_debounce, () {
      _timer = null;
      unawaited(_fetch(text, requestId));
    });
  }

  /// Fetches [query] again immediately, skipping the debounce.
  ///
  /// Does nothing unless [status] is [SearchStatus.error].
  void retry() {
    if (_disposed || _status != SearchStatus.error) {
      return;
    }

    // A query change may have scheduled a fetch that this one replaces.
    _timer?.cancel();
    _timer = null;
    _requestId++;

    unawaited(_fetch(_query, _requestId));
  }

  Future<void> _fetch(String text, int requestId) async {
    if (_disposed || requestId != _requestId) {
      return;
    }

    _status = SearchStatus.loading;
    notifyListeners();

    try {
      final List<String> fetched = await _fetcher(text);
      if (_disposed || requestId != _requestId) {
        return;
      }
      _results = List<String>.unmodifiable(fetched);
      _error = null;
      _status = SearchStatus.success;
    } catch (error) {
      if (_disposed || requestId != _requestId) {
        return;
      }
      _results = const <String>[];
      _error = error;
      _status = SearchStatus.error;
    }
    notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }
}

import 'dart:convert';

/// Smallest accepted value for [Settings.fontSize].
const int _minFontSize = 8;

/// Largest accepted value for [Settings.fontSize].
const int _maxFontSize = 72;

/// Value used for [Settings.locale] when the key is absent.
const String _defaultLocale = 'en';

/// Matches a language code, optionally followed by an upper case region.
final RegExp _localePattern = RegExp(r'^[a-z]{2}(_[A-Z]{2})?$');

/// User preferences that can be stored as, and restored from, JSON.
class Settings {
  /// Creates a settings snapshot.
  const Settings({
    required this.username,
    this.fontSize = 14,
    this.darkMode = false,
    this.tags = const [],
    this.locale = _defaultLocale,
  });

  /// Name of the user owning these settings. Never empty.
  final String username;

  /// Editor font size, always within 8..72 inclusive.
  final int fontSize;

  /// Whether the dark colour scheme is preferred.
  final bool darkMode;

  /// Free-form labels attached to the user. No tag is empty.
  final List<String> tags;

  /// Preferred locale, as two lower case letters optionally followed by an
  /// underscore and two upper case letters, such as `en` or `de_DE`.
  final String locale;

  /// Returns a JSON-encodable representation of these settings.
  Map<String, Object?> toJson() => <String, Object?>{
    'username': username,
    'fontSize': fontSize,
    'darkMode': darkMode,
    'tags': List<String>.of(tags),
    'locale': locale,
  };

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) {
      return true;
    }
    return other is Settings &&
        other.username == username &&
        other.fontSize == fontSize &&
        other.darkMode == darkMode &&
        other.locale == locale &&
        _tagsEqual(other.tags, tags);
  }

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags), locale);

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags, locale: $locale)';

  static bool _tagsEqual(List<String> a, List<String> b) {
    if (identical(a, b)) {
      return true;
    }
    if (a.length != b.length) {
      return false;
    }
    for (var i = 0; i < a.length; i++) {
      if (a[i] != b[i]) {
        return false;
      }
    }
    return true;
  }
}

/// Thrown when a JSON document cannot be read as a [Settings] value.
class SettingsFormatException implements Exception {
  /// Creates an exception describing why parsing failed.
  const SettingsFormatException(this.message);

  /// Human readable description of the problem. Mentions the offending key
  /// when the failure can be attributed to one.
  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

/// Parses [json] into a [Settings] value.
///
/// Throws a [SettingsFormatException] if the text is not a JSON object, if a
/// required key is missing, or if any known key holds a value of the wrong
/// type or outside its allowed range. No other exception type escapes.
Settings parseSettings(String json) {
  final Object? decoded;
  try {
    decoded = jsonDecode(json);
  } on Object {
    throw const SettingsFormatException('the text is not valid JSON');
  }
  if (decoded is! Map<String, Object?>) {
    throw const SettingsFormatException(
      'the top level of the document is not a JSON object',
    );
  }
  return Settings(
    username: _readUsername(decoded),
    fontSize: _readFontSize(decoded),
    darkMode: _readDarkMode(decoded),
    tags: _readTags(decoded),
    locale: _readLocale(decoded),
  );
}

String _readUsername(Map<String, Object?> map) {
  const key = 'username';
  if (!map.containsKey(key)) {
    throw const SettingsFormatException('"$key" is required but missing');
  }
  final value = map[key];
  if (value is! String) {
    throw const SettingsFormatException('"$key" must be a string');
  }
  if (value.isEmpty) {
    throw const SettingsFormatException('"$key" must not be empty');
  }
  return value;
}

int _readFontSize(Map<String, Object?> map) {
  const key = 'fontSize';
  if (!map.containsKey(key)) {
    return 14;
  }
  final value = map[key];
  final int size;
  if (value is int) {
    size = value;
  } else if (value is double &&
      value.isFinite &&
      value == value.roundToDouble()) {
    size = value.toInt();
  } else {
    throw const SettingsFormatException('"$key" must be an integer');
  }
  if (size < _minFontSize || size > _maxFontSize) {
    throw const SettingsFormatException(
      '"$key" must be within $_minFontSize..$_maxFontSize',
    );
  }
  return size;
}

bool _readDarkMode(Map<String, Object?> map) {
  const key = 'darkMode';
  if (!map.containsKey(key)) {
    return false;
  }
  final value = map[key];
  if (value is! bool) {
    throw const SettingsFormatException('"$key" must be a boolean');
  }
  return value;
}

List<String> _readTags(Map<String, Object?> map) {
  const key = 'tags';
  if (!map.containsKey(key)) {
    return const [];
  }
  final value = map[key];
  if (value is! List<Object?>) {
    throw const SettingsFormatException('"$key" must be a list of strings');
  }
  final tags = <String>[];
  for (final entry in value) {
    if (entry is! String) {
      throw const SettingsFormatException('"$key" must contain only strings');
    }
    if (entry.isEmpty) {
      throw const SettingsFormatException('"$key" must not contain empty tags');
    }
    tags.add(entry);
  }
  return tags;
}

String _readLocale(Map<String, Object?> map) {
  const key = 'locale';
  if (!map.containsKey(key)) {
    return _defaultLocale;
  }
  final value = map[key];
  if (value is! String) {
    throw const SettingsFormatException('"$key" must be a string');
  }
  if (!_localePattern.hasMatch(value)) {
    throw const SettingsFormatException(
      '"$key" must be a language code such as "en" or "de_DE"',
    );
  }
  return value;
}

import 'dart:async';

import 'package:flutter/material.dart';

/// Drives a countdown from [duration] down to zero, one second at a time.
///
/// The object that creates the controller owns it and is responsible for
/// calling [dispose].
class CountdownController extends ChangeNotifier {
  CountdownController({required Duration duration})
    : _duration = duration,
      _remaining = duration;

  static const Duration _tickInterval = Duration(seconds: 1);

  final Duration _duration;
  Duration _remaining;
  Timer? _timer;

  /// Time left before the countdown finishes. Starts at the duration the
  /// controller was created with.
  Duration get remaining => _remaining;

  /// Whether the countdown is currently ticking.
  bool get isRunning => _timer != null;

  /// Starts ticking. Does nothing while already running or once [remaining]
  /// has reached zero.
  void start() {
    if (isRunning || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_tickInterval, _tick);
    notifyListeners();
  }

  /// Stops ticking, keeping [remaining] where it is. Does nothing when the
  /// countdown is not running.
  void pause() {
    if (!isRunning) {
      return;
    }
    _stop();
    notifyListeners();
  }

  /// Adds [extra] to [remaining] and notifies listeners once.
  ///
  /// Works while the countdown is running, in which case ticking carries on
  /// from the new value, while it is paused, and after it has finished, in
  /// which case [start] can run it again.
  ///
  /// Throws an [ArgumentError] when [extra] is zero or negative, leaving the
  /// countdown untouched.
  void addTime(Duration extra) {
    if (extra <= Duration.zero) {
      throw ArgumentError.value(extra, 'extra', 'must be greater than zero');
    }
    _remaining += extra;
    notifyListeners();
  }

  /// Stops ticking and sets [remaining] back to the initial duration.
  void reset() {
    _stop();
    _remaining = _duration;
    notifyListeners();
  }

  @override
  void dispose() {
    _stop();
    super.dispose();
  }

  void _tick(Timer timer) {
    final Duration next = _remaining - _tickInterval;
    _remaining = next > Duration.zero ? next : Duration.zero;
    if (_remaining == Duration.zero) {
      _stop();
    }
    notifyListeners();
  }

  void _stop() {
    _timer?.cancel();
    _timer = null;
  }
}

/// Shows the [controller]'s remaining time as `mm:ss` along with start, pause,
/// reset and `+10s` buttons.
///
/// The widget never disposes the [controller]; the caller keeps ownership and
/// may hand the same controller to another [CountdownTimer] later.
class CountdownTimer extends StatefulWidget {
  const CountdownTimer({super.key, required this.controller, this.onFinished});

  final CountdownController controller;

  /// Called once when the countdown reaches zero.
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  static const Duration _extraTime = Duration(seconds: 10);

  bool _finished = false;

  @override
  void initState() {
    super.initState();
    _finished = widget.controller.remaining == Duration.zero;
    widget.controller.addListener(_handleControllerChanged);
  }

  @override
  void didUpdateWidget(CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_handleControllerChanged);
      _finished = widget.controller.remaining == Duration.zero;
      widget.controller.addListener(_handleControllerChanged);
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_handleControllerChanged);
    super.dispose();
  }

  void _handleControllerChanged() {
    if (!mounted) {
      return;
    }
    setState(() {});
    final bool atZero = widget.controller.remaining == Duration.zero;
    if (atZero && !_finished) {
      _finished = true;
      widget.onFinished?.call();
    } else if (!atZero) {
      _finished = false;
    }
  }

  void _handleAddTimePressed() {
    widget.controller.addTime(_extraTime);
  }

  static String _format(Duration remaining) {
    final String minutes = remaining.inMinutes.toString().padLeft(2, '0');
    final String seconds = (remaining.inSeconds % 60).toString().padLeft(
      2,
      '0',
    );
    return '$minutes:$seconds';
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: <Widget>[
        Text(_format(widget.controller.remaining)),
        Row(
          mainAxisSize: MainAxisSize.min,
          children: <Widget>[
            TextButton(
              onPressed: widget.controller.start,
              child: const Text('Start'),
            ),
            TextButton(
              onPressed: widget.controller.pause,
              child: const Text('Pause'),
            ),
            TextButton(
              onPressed: widget.controller.reset,
              child: const Text('Reset'),
            ),
            TextButton(
              onPressed: _handleAddTimePressed,
              child: const Text('+10s'),
            ),
          ],
        ),
      ],
    );
  }
}

import 'dart:async';

import 'package:flutter/foundation.dart';

/// Fetches the results for [query].
typedef SearchFetcher = Future<List<String>> Function(String query);

/// The state of the latest search.
enum SearchStatus { idle, loading, success, error }

/// Debounced search state holder.
///
/// Text changes are stored immediately, but a fetch only starts once the
/// debounce duration has elapsed without another change. Responses that no
/// longer match the current query are dropped, so stale results can never
/// overwrite newer ones.
class SearchModel extends ChangeNotifier {
  SearchModel({
    required this._fetcher,
    this._debounce = const Duration(milliseconds: 300),
  });

  final SearchFetcher _fetcher;
  final Duration _debounce;

  Timer? _timer;

  /// Incremented whenever the query changes, a retry starts or the model is
  /// disposed, so that in-flight fetches started for an older value can be
  /// identified and discarded.
  int _generation = 0;
  bool _disposed = false;

  SearchStatus _status = SearchStatus.idle;
  String _query = '';
  List<String> _results = const <String>[];
  Object? _error;

  SearchStatus get status => _status;

  /// The latest text passed to [onQueryChanged].
  String get query => _query;

  /// The results of the latest successful fetch. Unmodifiable.
  List<String> get results => _results;

  /// The error of the latest failed fetch, or `null`.
  Object? get error => _error;

  void onQueryChanged(String text) {
    if (_disposed || text == _query) {
      return;
    }
    _query = text;
    _timer?.cancel();
    _timer = null;
    _generation++;

    if (text.isEmpty) {
      _status = SearchStatus.idle;
      _results = const <String>[];
      _error = null;
      notifyListeners();
      return;
    }

    notifyListeners();
    final generation = _generation;
    _timer = Timer(_debounce, () => _fetch(text, generation));
  }

  /// Re-runs the fetch for the current [query] after an error.
  ///
  /// Does nothing unless [status] is [SearchStatus.error]. The fetch starts
  /// immediately, without waiting for the debounce, and its response is
  /// dropped if the query changes while it is in flight.
  void retry() {
    if (_disposed || _status != SearchStatus.error) {
      return;
    }
    _timer?.cancel();
    _timer = null;
    _generation++;
    unawaited(_fetch(_query, _generation));
  }

  Future<void> _fetch(String text, int generation) async {
    if (_disposed || generation != _generation) {
      return;
    }
    _timer = null;
    _status = SearchStatus.loading;
    _error = null;
    notifyListeners();

    try {
      final values = await _fetcher(text);
      if (_disposed || generation != _generation) {
        return;
      }
      _results = List<String>.unmodifiable(values);
      _status = SearchStatus.success;
      _error = null;
    } catch (error) {
      if (_disposed || generation != _generation) {
        return;
      }
      _results = const <String>[];
      _error = error;
      _status = SearchStatus.error;
    }
    notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _generation++;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }
}

import 'dart:convert';

/// User-facing configuration that can be serialised to and from JSON.
class Settings {
  const Settings({
    required this.username,
    this.fontSize = 14,
    this.darkMode = false,
    this.tags = const [],
    this.locale = 'en',
  });

  /// The account name. Never empty.
  final String username;

  /// The editor font size, always within [minFontSize] .. [maxFontSize].
  final int fontSize;

  /// Whether the dark colour scheme is selected.
  final bool darkMode;

  /// Free-form labels. Never contains an empty entry.
  final List<String> tags;

  /// The language tag, always matching [localePattern].
  final String locale;

  /// Smallest accepted value for [fontSize].
  static const int minFontSize = 8;

  /// Largest accepted value for [fontSize].
  static const int maxFontSize = 72;

  /// The shape accepted for [locale]: two lowercase letters, optionally
  /// followed by an underscore and two uppercase letters.
  static final RegExp localePattern = RegExp(r'^[a-z]{2}(_[A-Z]{2})?$');

  /// The JSON representation understood by [parseSettings].
  Map<String, Object?> toJson() {
    return <String, Object?>{
      'username': username,
      'fontSize': fontSize,
      'darkMode': darkMode,
      'tags': List<String>.of(tags),
      'locale': locale,
    };
  }

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) {
      return true;
    }
    return other is Settings &&
        other.username == username &&
        other.fontSize == fontSize &&
        other.darkMode == darkMode &&
        other.locale == locale &&
        _tagsEqual(other.tags, tags);
  }

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags), locale);

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags, locale: $locale)';

  static bool _tagsEqual(List<String> a, List<String> b) {
    if (identical(a, b)) {
      return true;
    }
    if (a.length != b.length) {
      return false;
    }
    for (var i = 0; i < a.length; i++) {
      if (a[i] != b[i]) {
        return false;
      }
    }
    return true;
  }
}

/// Thrown when a JSON document cannot be turned into a [Settings].
class SettingsFormatException implements Exception {
  const SettingsFormatException(this.message);

  /// Human readable description of the problem.
  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

/// Parses [json] into a [Settings].
///
/// Throws a [SettingsFormatException] if the text is not a JSON object, if a
/// required key is missing, or if a value has the wrong type or is out of
/// range. No other exception type escapes this function.
Settings parseSettings(String json) {
  final Object? decoded;
  try {
    decoded = jsonDecode(json);
  } on FormatException catch (error) {
    throw SettingsFormatException('not valid JSON: ${error.message}');
  }

  if (decoded is! Map<String, Object?>) {
    throw const SettingsFormatException('top level value is not a JSON object');
  }

  return Settings(
    username: _readUsername(decoded),
    fontSize: _readFontSize(decoded),
    darkMode: _readDarkMode(decoded),
    tags: _readTags(decoded),
    locale: _readLocale(decoded),
  );
}

String _readUsername(Map<String, Object?> map) {
  const key = 'username';
  if (!map.containsKey(key)) {
    throw const SettingsFormatException('missing required key "$key"');
  }
  final value = map[key];
  if (value is! String) {
    throw const SettingsFormatException('key "$key" must be a string');
  }
  if (value.isEmpty) {
    throw const SettingsFormatException('key "$key" must not be empty');
  }
  return value;
}

int _readFontSize(Map<String, Object?> map) {
  const key = 'fontSize';
  if (!map.containsKey(key)) {
    return 14;
  }
  final value = map[key];
  final int size;
  if (value is int) {
    size = value;
  } else if (value is double) {
    if (!value.isFinite || value != value.roundToDouble()) {
      throw const SettingsFormatException('key "$key" must be an integer');
    }
    size = value.toInt();
  } else {
    throw const SettingsFormatException('key "$key" must be an integer');
  }
  if (size < Settings.minFontSize || size > Settings.maxFontSize) {
    throw const SettingsFormatException(
      'key "$key" must be between ${Settings.minFontSize} '
      'and ${Settings.maxFontSize}',
    );
  }
  return size;
}

bool _readDarkMode(Map<String, Object?> map) {
  const key = 'darkMode';
  if (!map.containsKey(key)) {
    return false;
  }
  final value = map[key];
  if (value is! bool) {
    throw const SettingsFormatException('key "$key" must be a boolean');
  }
  return value;
}

List<String> _readTags(Map<String, Object?> map) {
  const key = 'tags';
  if (!map.containsKey(key)) {
    return const <String>[];
  }
  final value = map[key];
  if (value is! List<Object?>) {
    throw const SettingsFormatException('key "$key" must be a list of strings');
  }
  final tags = <String>[];
  for (final entry in value) {
    if (entry is! String) {
      throw const SettingsFormatException(
        'key "$key" must contain only strings',
      );
    }
    if (entry.isEmpty) {
      throw const SettingsFormatException(
        'key "$key" must not contain empty strings',
      );
    }
    tags.add(entry);
  }
  return List<String>.unmodifiable(tags);
}

String _readLocale(Map<String, Object?> map) {
  const key = 'locale';
  if (!map.containsKey(key)) {
    return 'en';
  }
  final value = map[key];
  if (value is! String) {
    throw const SettingsFormatException('key "$key" must be a string');
  }
  if (!Settings.localePattern.hasMatch(value)) {
    throw const SettingsFormatException(
      'key "$key" must be a language code such as "en" or "de_DE"',
    );
  }
  return value;
}
